'use client'

import { useCallback, useEffect, useMemo, useState } from 'react'
import { ChevronDown, Circle, Disc3, Music2, Play, Plus, Search, Square, Triangle, X } from 'lucide-react'
import { dataSources } from '@/lib/data-sources'

type SourceKey = 'all' | 'spotify' | 'household' | 'indiaTransactions'
type Row = Record<string, string>

const menuItems = [
  ['STORY MODE', 'Turn connected moments into an interactive story.'],
  ['JOURNEY MODE', 'Explore the digital journey and discover periods of unusual activity.'],
  ['RECEIPT ARCHIVE', 'Browse the individual fragments that make up the archive.'],
  ['CONNECT THE DOTS', 'Discover relationships between moments that appear unrelated.'],
  ['PATTERN LAB', 'Explore recurring activity, clusters and hidden patterns.'],
  ['SETTINGS', 'Configure the archive experience.'],
] as const
const sourceLabels: Record<SourceKey, string> = { all: 'ALL', spotify: 'MUSIC', household: 'HOUSEHOLD', indiaTransactions: 'TRANSACTIONS' }
const sourceOrder: SourceKey[] = ['all', 'spotify', 'household', 'indiaTransactions']

function parseCsv(text: string): Row[] {
  const rows: string[][] = []; let row: string[] = []; let cell = ''; let quoted = false
  for (let i = 0; i < text.length; i++) { const char = text[i]; const next = text[i + 1]; if (char === '"') { if (quoted && next === '"') { cell += '"'; i++ } else quoted = !quoted } else if (char === ',' && !quoted) { row.push(cell); cell = '' } else if ((char === '\n' || char === '\r') && !quoted) { if (char === '\r' && next === '\n') i++; row.push(cell); if (row.some(Boolean)) rows.push(row); row = []; cell = '' } else cell += char }
  if (cell || row.length) { row.push(cell); rows.push(row) }
  const headers = rows.shift()?.map((value) => value.trim()) ?? []
  return rows.map((values) => Object.fromEntries(headers.map((header, index) => [header, values[index]?.trim() ?? ''])))
}

let dataPromise: Promise<Record<Exclude<SourceKey, 'all'>, Row[]>> | null = null
function loadArchiveData() {
  if (!dataPromise) dataPromise = Promise.all(Object.entries(dataSources).map(async ([key, source]) => { const texts = await Promise.all(source.files.map(async (file) => { const response = await fetch(file); if (!response.ok) throw new Error(`Failed to load ${file}`); return response.text() })); return [key, texts.flatMap(parseCsv)] as const })).then(Object.fromEntries as never)
  return dataPromise
}

function HudClock() { const [now, setNow] = useState(new Date()); useEffect(() => { const timer = window.setInterval(() => setNow(new Date()), 1000); return () => window.clearInterval(timer) }, []); return <div className="hud-time"><span>TIME</span><strong suppressHydrationWarning>{now.toLocaleTimeString('en-GB', { hour12: false })}</strong><span>DATE</span><strong suppressHydrationWarning>{now.toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: '2-digit' })}</strong></div> }
function GameHeader({ archive = false }: { archive?: boolean }) { return <header className="game-header"><div className="game-logo"><span>{'LIFE//RECEIPTS'}</span><small>{archive ? 'RECEIPT ARCHIVE' : 'DIGITAL LIFE ARCHIVE'}</small></div><div className="header-hud"><div className="hud-actions"><span><Triangle /> CUSTOMIZE</span><span><Square /> {archive ? 'ARCHIVE' : 'ARCHIVE'}</span></div><HudClock /><div className="online"><i /> STATUS&nbsp; ONLINE</div></div></header> }
type ArchiveStats = { receipts: number; years: string; connections: number; chapters: number }
let statsPromise: Promise<ArchiveStats> | null = null
function getArchiveStats(data: Record<Exclude<SourceKey, 'all'>, Row[]>): ArchiveStats { const all = Object.values(data).flat(); const years = all.map((row) => { const value = row.ts || row.Date || row.trans_date_trans_time || ''; const year = new Date(value.replace(' UTC', '')).getFullYear(); return Number.isFinite(year) && year > 1900 ? year : null }).filter((year): year is number => year !== null); const seed = data.spotify[0]; let connections = 0; if (seed) connections = (Object.entries(data) as [Exclude<SourceKey, 'all'>, Row[]][]).flatMap(([source, rows]) => rows.filter((row) => row !== seed).map((row) => connectionScore(seed, 'spotify', row, source))).filter(Boolean).length; return { receipts: all.length, years: years.length ? `${Math.min(...years)} — ${Math.max(...years)}` : '0', connections, chapters: buildStoryCandidates(data).length } }
function loadArchiveStats() { if (!statsPromise) statsPromise = loadArchiveData().then(getArchiveStats); return statsPromise }
function ArchiveStatus() { const [stats, setStats] = useState<ArchiveStats | null>(null); useEffect(() => { let alive = true; loadArchiveStats().then((value) => alive && setStats(value)); return () => { alive = false } }, []); return <div className="archive-status"><div className="status-heading"><span>ARCHIVE STATUS</span><i aria-label={stats ? 'Dataset ready' : 'Dataset loading'} /></div><div className="status-grid"><span>RECEIPTS</span><b>{stats ? stats.receipts.toLocaleString() : '...'}</b><span>YEARS</span><b>{stats?.years || '...'}</b><span>CONNECTIONS</span><b>{stats ? stats.connections : '...'}</b><span>CHAPTERS</span><b>{stats ? stats.chapters : '...'}</b></div></div> }
function ArchiveCore() { return <div className="core-stage" aria-label="Abstract digital memory core illustration"><div className="core-glow" /><div className="core-orbit orbit-one" /><div className="core-orbit orbit-two" /><div className="core-orbit orbit-three" /><div className="timeline-mark mark-a">2004</div><div className="timeline-mark mark-b">NOW</div><div className="core-diamond"><span>MEMORY<br />CORE</span></div><div className="core-layer layer-a" /><div className="core-layer layer-b" /><div className="core-node node-1" /><div className="core-node node-2" /><div className="core-node node-3" /><div className="core-node node-4" /><div className="core-node node-5" /><div className="core-fragment fragment-a">01 / REC</div><div className="core-fragment fragment-b">TXN_204</div><Music2 className="core-music" aria-hidden="true" /><span className="transaction-symbol">$</span><p className="core-caption">DIGITAL MEMORY CORE // STANDBY</p></div> }

function MainMenu({ onStory, onArchive, onConnect, onPatternLab, onSettings }: { onStory: () => void; onArchive: () => void; onConnect: () => void; onPatternLab: () => void; onSettings: () => void }) {
  const [selected, setSelected] = useState(0); const [transitioning, setTransitioning] = useState(false); const item = menuItems[selected]
  const choose = useCallback((index: number) => { setSelected(index); setTransitioning(true); window.setTimeout(() => setTransitioning(false), 360) }, [])
  useEffect(() => { const onKeyDown = (event: KeyboardEvent) => { if (event.key === 'ArrowDown') { event.preventDefault(); choose((selected + 1) % menuItems.length) }; if (event.key === 'ArrowUp') { event.preventDefault(); choose((selected - 1 + menuItems.length) % menuItems.length) }; if (event.key === 'Enter' && (selected === 0 || selected === 1)) { event.preventDefault(); onStory() }; if (event.key === 'Enter' && selected === 2) { event.preventDefault(); onArchive() }; if (event.key === 'Enter' && selected === 3) { event.preventDefault(); onConnect() }; if (event.key === 'Enter' && selected === 4) { event.preventDefault(); onPatternLab() }; if (event.key === 'Enter' && selected === 5) { event.preventDefault(); onSettings() } }; window.addEventListener('keydown', onKeyDown); return () => window.removeEventListener('keydown', onKeyDown) }, [choose, onArchive, onConnect, onPatternLab, onSettings, onStory, selected])
  return <main className={`game-shell ${transitioning ? 'screen-transition' : ''}`}><div className="game-bg-art" aria-hidden="true"><div className="silhouette" /><div className="map-lines" /><div className="wave wave-a" /><div className="wave wave-b" /><div className="receipt-shard shard-a" /><div className="receipt-shard shard-b" /><div className="photo-fragment photo-a" /><div className="photo-fragment photo-b" /></div><GameHeader /><div className="game-layout"><section className="menu-column" aria-label="Main menu"><div className="menu-label"><span>MAIN MENU</span><b>{String(selected + 1).padStart(2, '0')} / 06</b></div><nav className="game-menu" aria-label="Archive modes">{menuItems.map(([label], index) => <button key={label} className={index === selected ? 'menu-item selected' : 'menu-item'} onMouseEnter={() => choose(index)} onFocus={() => choose(index)} onClick={() => index === 0 || index === 1 ? onStory() : index === 2 ? onArchive() : index === 3 ? onConnect() : index === 4 ? onPatternLab() : index === 5 ? onSettings() : undefined} aria-current={index === selected ? 'true' : undefined}><span className="menu-cursor" aria-hidden="true"><i /></span><span>{label}</span><small>{String(index + 1).padStart(2, '0')}</small></button>)}</nav><ArchiveStatus /></section><section className="visual-column"><ArchiveCore /><div className="description-panel" aria-live="polite"><div className="panel-mark"><Plus /></div><div><span className="panel-kicker">RECEIPT ARCHIVE // SELECTED</span><p key={item[0]}>{item[1]}</p></div><ChevronDown className="panel-arrow" aria-hidden="true" /></div></section></div><footer className="game-footer"><div className="player-line"><span>PLAYER</span><strong>{'LIFE//RECEIPTS'}</strong></div><div className="controls"><span><Triangle /> SELECT</span><span><Circle /> BACK</span><span><Play /> START</span></div><div className="manual"><Disc3 /> MANUAL<br /><b>START</b></div></footer></main>
}

function formatDate(row: Row, source: Exclude<SourceKey, 'all'>) { const value = source === 'spotify' ? row.ts : source === 'household' ? row.Date : row.trans_date_trans_time; return value?.replace('T', ' ').replace(' UTC', '') || 'DATE UNKNOWN' }
function money(value: string) { const number = Number(value); return Number.isFinite(number) ? number.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : value }
function ReceiptRow({ row, source, selected, onClick }: { row: Row; source: Exclude<SourceKey, 'all'>; selected: boolean; onClick: () => void }) { const isMusic = source === 'spotify'; const isHousehold = source === 'household'; return <button className={`receipt-row ${selected ? 'receipt-selected' : ''}`} onClick={onClick}><span className="receipt-cursor">▶</span><div className="receipt-main"><div className="receipt-type">{isMusic ? 'MUSIC' : isHousehold ? 'HOUSEHOLD' : 'TRANSACTION'} <small>{formatDate(row, source)}</small></div><strong>{isMusic ? row.track_name || 'UNTITLED TRACK' : isHousehold ? row.Category || 'UNCATEGORIZED' : row.merchant || 'UNKNOWN MERCHANT'}</strong><span>{isMusic ? `${row.artist_name || 'UNKNOWN ARTIST'} // ${row.album_name || 'UNKNOWN ALBUM'}` : isHousehold ? `${row.Subcategory || 'GENERAL'} // ${row['Income/Expense'] || 'UNSPECIFIED'}` : `${row.category || 'GENERAL'} // ${row.city || 'UNKNOWN CITY'}, ${row.state || ''}`}</span></div><div className="receipt-value">{isMusic ? `${Math.round(Number(row.ms_played || 0) / 60000)} MIN` : `${row.Currency || '₹'} ${money(row.Amount || row.amt || '0')}`}</div></button> }
function Filters({ source, rows, search, setSearch, filters, setFilters }: { source: SourceKey; rows: Row[]; search: string; setSearch: (value: string) => void; filters: Record<string, string>; setFilters: (value: Record<string, string>) => void }) { const field = (label: string, key: string, values: string[]) => <label className="archive-filter">{label}<select value={filters[key] || ''} onChange={(event) => setFilters({ ...filters, [key]: event.target.value })}><option value="">ALL</option>{values.slice(0, 120).map((value) => <option key={value} value={value}>{value}</option>)}</select></label>; const unique = (key: string) => [...new Set(rows.map((row) => row[key]).filter(Boolean))].sort(); return <aside className="archive-sidebar"><div className="archive-kicker">SOURCE SELECTOR</div><div className="source-menu">{sourceOrder.map((key) => <button key={key} className={source === key ? 'source-item source-active' : 'source-item'} onClick={() => setFilters({ ...filters, __source: key })}>{sourceLabels[key]}<small>{key === 'all' ? 'ALL DATA' : key === 'spotify' ? 'SPOTIFY' : key === 'household' ? 'DAILY LOG' : 'CARD LOG'}</small></button>)}</div><div className="archive-kicker filter-kicker">SEARCH ARCHIVE</div><div className="archive-search"><Search /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="SEARCH RECEIPTS" aria-label="Search archive" /></div>{source === 'spotify' && <>{field('ARTIST', 'artist_name', unique('artist_name'))}{field('PLATFORM', 'platform', unique('platform'))}{field('SKIPPED', 'skipped', unique('skipped'))}</>}{source === 'household' && <>{field('CATEGORY', 'Category', unique('Category'))}{field('SUBCATEGORY', 'Subcategory', unique('Subcategory'))}{field('INCOME / EXPENSE', 'Income/Expense', unique('Income/Expense'))}</>}{source === 'indiaTransactions' && <>{field('CATEGORY', 'category', unique('category'))}{field('CITY', 'city', unique('city'))}{field('STATE', 'state', unique('state'))}</>}<div className="date-label">DATE RANGE <span>INDEXED</span></div></aside> }
function Detail({ row, source, onClose, onConnect }: { row: Row | null; source: Exclude<SourceKey, 'all'> | null; onClose: () => void; onConnect: (row: Row, source: Exclude<SourceKey, 'all'>) => void }) { if (!row || !source) return <aside className="detail-panel empty-detail"><span className="notice-kicker">RECEIPT DETAIL</span><strong>SELECT A RECEIPT</strong><span>Use arrow keys or select a record from the archive index.</span></aside>; const music = source === 'spotify'; const household = source === 'household'; return <aside className="detail-panel"><button className="detail-close" onClick={onClose} aria-label="Close receipt detail"><X /></button><span className="notice-kicker">RECEIPT DETAIL</span><div className="detail-title">{music ? 'MUSIC' : household ? 'HOUSEHOLD' : 'TRANSACTION'}</div><h2>{music ? row.track_name : household ? row.Category : row.merchant}</h2><div className="detail-grid">{music ? <><span>ARTIST</span><b>{row.artist_name || 'UNKNOWN'}</b><span>ALBUM</span><b>{row.album_name || 'UNKNOWN'}</b><span>DATE / TIME</span><b>{formatDate(row, source)}</b><span>PLATFORM</span><b>{row.platform || 'UNKNOWN'}</b><span>DURATION</span><b>{Math.round(Number(row.ms_played || 0) / 1000)} SEC</b><span>SKIPPED</span><b>{row.skipped || 'UNKNOWN'}</b></> : household ? <><span>SUBCATEGORY</span><b>{row.Subcategory || 'GENERAL'}</b><span>DATE</span><b>{formatDate(row, source)}</b><span>AMOUNT</span><b>{row.Currency || ''} {money(row.Amount || '0')}</b><span>TYPE</span><b>{row['Income/Expense'] || 'UNKNOWN'}</b><span>NOTE</span><b>{row.Note || 'NONE'}</b></> : <><span>DATE / TIME</span><b>{formatDate(row, source)}</b><span>AMOUNT</span><b>₹ {money(row.amt || '0')}</b><span>CITY</span><b>{row.city || 'UNKNOWN'}</b><span>STATE</span><b>{row.state || 'UNKNOWN'}</b><span>CATEGORY</span><b>{row.category || 'UNKNOWN'}</b></>}</div><button className="connect-button" onClick={() => onConnect(row, source)}>[ CONNECT THE DOTS ]</button></aside> }

function ArchiveScreen({ onBack, onConnect, initialSource, initialSearch }: { onBack: () => void; onConnect: (row: Row, source: Exclude<SourceKey, 'all'>) => void; initialSource?: Exclude<SourceKey,'all'>; initialSearch?: string }) { const [status, setStatus] = useState('DECODING ARCHIVE...'); const [data, setData] = useState<Record<Exclude<SourceKey, 'all'>, Row[]> | null>(null); const [source, setSource] = useState<SourceKey>(initialSource || 'all'); const [search, setSearch] = useState(initialSearch || ''); const [filters, setFilters] = useState<Record<string, string>>({}); const [page, setPage] = useState(0); const [selected, setSelected] = useState(0); const [detail, setDetail] = useState<Row | null>(null); const [detailSource, setDetailSource] = useState<Exclude<SourceKey, 'all'> | null>(null)
  useEffect(() => { let alive = true; loadArchiveData().then((loaded) => { if (!alive) return; setStatus('LOADING RECEIPTS...'); setData(loaded); window.setTimeout(() => alive && setStatus('ARCHIVE READY.'), 500) }).catch(() => alive && setStatus('ARCHIVE ERROR // CHECK DATA')); return () => { alive = false } }, [])
  const actualSource = source === 'all' ? 'spotify' : source; const rows = useMemo(() => { if (!data) return []; const pools = source === 'all' ? [data.spotify, data.household, data.indiaTransactions].flat() : data[source]; const query = search.slice(0, 200).toLowerCase().trim(); return pools.filter((row) => { const haystack = source === 'spotify' ? [row.track_name, row.artist_name, row.album_name] : source === 'household' ? [row.Category, row.Subcategory, row.Note] : source === 'indiaTransactions' ? [row.merchant, row.category, row.city, row.state] : [...dataSources.spotify.safeFields, ...dataSources.household.safeFields, ...dataSources.indiaTransactions.safeFields].map((field) => row[field]); return (!query || haystack.some((value) => value?.toLowerCase().includes(query))) && Object.entries(filters).every(([key, value]) => key === '__source' || !value || row[key] === value) }) }, [data, filters, search, source]); const pageRows = useMemo(() => rows.slice(page * 25, page * 25 + 25), [page, rows]); const selectedRow = pageRows[selected] ?? null
  useEffect(() => { const onKey = (event: KeyboardEvent) => { if (event.key === 'Escape') { if (detail) setDetail(null); else onBack() } if (event.key === 'ArrowDown') { event.preventDefault(); setSelected((value) => Math.min(value + 1, pageRows.length - 1)) } if (event.key === 'ArrowUp') { event.preventDefault(); setSelected((value) => Math.max(value - 1, 0)) } if (event.key === 'Enter' && selectedRow) setDetail(selectedRow) }; window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey) }, [detail, onBack, pageRows.length, selectedRow])
  const resetSelection = () => { setPage(0); setSelected(0); setDetail(null); setDetailSource(null) }; const changeSource = (value: SourceKey) => { setSource(value); setFilters({}); resetSelection() }; const changeSearch = (value: string) => { setSearch(value); resetSelection() }; const changeFilters = (value: Record<string, string>) => { setFilters(value); resetSelection() }; const totalPages = Math.max(1, Math.ceil(rows.length / 25)); return <main className="game-shell archive-shell"><div className="game-bg-art" aria-hidden="true"><div className="silhouette" /><div className="map-lines" /><div className="wave wave-a" /><div className="receipt-shard shard-a" /><div className="photo-fragment photo-a" /><div className="photo-fragment photo-b" /></div><GameHeader archive /><div className="archive-topbar"><div><span className="archive-kicker">RECEIPT ARCHIVE</span><h1>ARCHIVE STATUS: ONLINE</h1></div><div className="loaded-count"><span>LOADED RECORDS</span><strong>{data ? (source === 'all' ? Object.values(data).flat().length : data[source].length).toLocaleString() : '----'}</strong></div><button className="back-button" onClick={onBack}>◀ MAIN MENU</button></div>{!data ? <div className="archive-loading"><strong>{status}</strong><span>{status === 'ARCHIVE READY.' ? 'INDEX COMPLETE.' : 'PLEASE WAIT...'}</span></div> : <div className="archive-layout"><Filters source={source} rows={source === 'all' ? [...data.spotify, ...data.household, ...data.indiaTransactions] : data[source]} search={search} setSearch={changeSearch} filters={{ ...filters, __source: source }} setFilters={(next) => { const nextSource = next.__source as SourceKey | undefined; if (nextSource) changeSource(nextSource); else changeFilters(next) }} /><section className="receipt-index"><div className="index-heading"><span>RECEIPT INDEX // {sourceLabels[source]}</span><b>{rows.length.toLocaleString()} RECORDS</b></div><div className="receipt-list">{pageRows.map((row, index) => <ReceiptRow key={`${index}-${formatDate(row, actualSource)}`} row={row} source={source === 'all' ? (data.spotify.includes(row) ? 'spotify' : data.household.includes(row) ? 'household' : 'indiaTransactions') : source} selected={index === selected} onClick={() => { const rowSource = source === 'all' ? (data.spotify.includes(row) ? 'spotify' : data.household.includes(row) ? 'household' : 'indiaTransactions') : source; setSelected(index); setDetail(row); setDetailSource(rowSource) }} />)}{!pageRows.length && <div className="no-results">NO RECEIPTS MATCH THE CURRENT INDEX.</div>}</div><div className="pagination"><button disabled={page === 0} onClick={() => { setPage((value) => value - 1); setSelected(0) }}>◀ PREV</button><span>PAGE {String(page + 1).padStart(2, '0')} / {String(totalPages).padStart(2, '0')}</span><button disabled={page >= totalPages - 1} onClick={() => { setPage((value) => value + 1); setSelected(0) }}>NEXT ▶</button></div></section><Detail row={detail} source={detail ? detailSource : null} onClose={() => setDetail(null)} onConnect={onConnect} /></div>}<footer className="game-footer"><div className="player-line"><span>PLAYER</span><strong>RECEIPT ARCHIVE</strong></div><div className="controls"><span><Triangle /> SELECT</span><span><Circle /> BACK</span><span><Play /> OPEN</span></div><div className="manual"><Disc3 /> ESC<br /><b>RETURN</b></div></footer></main> }

type Connection = { row: Row; source: Exclude<SourceKey, 'all'>; score: number; reasons: string[]; minutes: number; records: number; group: Row[] }
function rowTime(row: Row, source: Exclude<SourceKey, 'all'>) { const raw = source === 'spotify' ? row.ts : source === 'household' ? row.Date : row.trans_date_trans_time; const date = raw ? new Date(raw.replace(' UTC', '')) : null; return date && !Number.isNaN(date.getTime()) ? date : null }
function rowTitle(row: Row, source: Exclude<SourceKey, 'all'>) { return source === 'spotify' ? row.track_name || 'UNTITLED TRACK' : source === 'household' ? row.Category || 'UNCATEGORIZED' : row.merchant || 'UNKNOWN MERCHANT' }
function minutesLabel(minutes: number) { return minutes < 1 ? `${Math.round(minutes * 60)} sec apart` : minutes < 60 ? `${Math.round(minutes)} min apart` : `${Math.round(minutes / 60 * 10) / 10} hr apart` }
function connectionScore(selected: Row, selectedSource: Exclude<SourceKey, 'all'>, candidate: Row, candidateSource: Exclude<SourceKey, 'all'>, group: Row[] = [candidate]): Connection | null { const a = rowTime(selected, selectedSource); const b = rowTime(candidate, candidateSource); if (!a || !b) return null; const minutes = Math.abs(a.getTime() - b.getTime()) / 60000; let score = minutes < 5 ? 35 : minutes < 15 ? 28 : minutes < 30 ? 20 : minutes < 60 ? 12 : minutes <= 180 ? 6 : 0; const reasons: string[] = []; if (score > 0) reasons.push(minutesLabel(minutes)); const selectedArtist = selectedSource === 'spotify' ? selected.artist_name?.toLowerCase() : ''; const candidateArtist = candidateSource === 'spotify' ? candidate.artist_name?.toLowerCase() : ''; const sameArtist = Boolean(selectedArtist && candidateArtist && selectedArtist === candidateArtist); const sameTrack = selectedSource === 'spotify' && candidateSource === 'spotify' && Boolean(selected.track_name && candidate.track_name && selected.track_name.toLowerCase() === candidate.track_name.toLowerCase()); if (sameArtist) { score += 30; reasons.unshift('Same artist') } if (sameTrack) { score += 25; reasons.unshift('Same track') } const categoryA = selectedSource === 'household' ? selected.Category : selectedSource === 'indiaTransactions' ? selected.category : ''; const categoryB = candidateSource === 'household' ? candidate.Category : candidateSource === 'indiaTransactions' ? candidate.category : ''; if (categoryA && categoryB && categoryA.toLowerCase() === categoryB.toLowerCase()) { score += 10; reasons.push('Same category') } const keywordA = `${selected.track_name || ''} ${selected.artist_name || ''} ${selected.Category || ''} ${selected.category || ''}`.toLowerCase().split(/[^a-z0-9]+/).filter((word) => word.length > 4); const keywordB = `${candidate.track_name || ''} ${candidate.artist_name || ''} ${candidate.Category || ''} ${candidate.category || ''}`.toLowerCase(); if (keywordA.some((word) => keywordB.includes(word)) && !sameArtist && !sameTrack) { score += 10; reasons.push('Shared keyword') } const activityCluster = selectedSource === candidateSource && minutes <= 15 && (sameArtist || sameTrack); if (activityCluster) { score += 10; reasons.push('Same listening period') } const strongSignal = sameArtist || sameTrack || minutes < 5 || (categoryA && categoryB && categoryA.toLowerCase() === categoryB.toLowerCase()) || keywordA.some((word) => keywordB.includes(word)); if (!strongSignal || score < 40) return null; const groupTimes = group.map((item) => rowTime(item, candidateSource)?.getTime()).filter((time): time is number => typeof time === 'number'); const groupMinutes = groupTimes.length > 1 ? (Math.max(...groupTimes) - Math.min(...groupTimes)) / 60000 : minutes; return { row: candidate, source: candidateSource, score: Math.min(score, 100), reasons: [...new Set(reasons)], minutes: groupMinutes, records: group.length, group } }
function connectionLabel(source: Exclude<SourceKey, 'all'>) { return source === 'spotify' ? 'MUSIC' : source === 'household' ? 'HOUSEHOLD' : 'TRANSACTION' }
function ConnectionCard({ connection, index, selected, onClick }: { connection: Connection; index: number; selected: boolean; onClick: () => void }) { const grouped = connection.records > 1; return <button className={`connection-card ${selected ? 'connection-card-active' : ''}`} onClick={onClick}><span className="connection-index">{String(index + 1).padStart(2, '0')}</span><span className="connection-copy"><strong>{rowTitle(connection.row, connection.source)}</strong><small>{grouped ? `${connection.records} ${connection.source === 'spotify' ? 'LISTENING RECORDS' : 'RECORDS'} // ${minutesLabel(connection.minutes)}` : `${connectionLabel(connection.source)} // ${formatDate(connection.row, connection.source)}`}</small><span>{connection.reasons.map((reason) => `+ ${reason}`).join('  ')}</span></span><b>{connection.score}%</b></button> }
function ConnectScreen({ onBack, initialSelection }: { onBack: () => void; initialSelection?: { row: Row; source: Exclude<SourceKey, 'all'> } }) { const [data, setData] = useState<Record<Exclude<SourceKey, 'all'>, Row[]> | null>(null); const [selected, setSelected] = useState<{ row: Row; source: Exclude<SourceKey, 'all'> } | null>(null); const [active, setActive] = useState(0); useEffect(() => { loadArchiveData().then((loaded) => { setData(loaded); setSelected(initialSelection ?? { row: loaded.spotify[0], source: 'spotify' }) }) }, [initialSelection]); const connections = useMemo(() => { if (!data || !selected?.row) return []; const candidates = (Object.entries(data) as [Exclude<SourceKey, 'all'>, Row[]][]).flatMap(([source, rows]) => rows.filter((row) => row !== selected.row).map((row) => { const isDuplicateMusic = source === 'spotify' && selected.source === 'spotify' && row.track_name?.toLowerCase() === selected.row.track_name?.toLowerCase() && row.artist_name?.toLowerCase() === selected.row.artist_name?.toLowerCase() && row.album_name?.toLowerCase() === selected.row.album_name?.toLowerCase(); const group = isDuplicateMusic ? rows.filter((peer) => peer.track_name?.toLowerCase() === row.track_name?.toLowerCase() && peer.artist_name?.toLowerCase() === row.artist_name?.toLowerCase() && peer.album_name?.toLowerCase() === row.album_name?.toLowerCase() && Math.abs((rowTime(peer, source)?.getTime() ?? 0) - (rowTime(row, source)?.getTime() ?? 0)) <= 10 * 60000) : [row]; return connectionScore(selected.row, selected.source, row, source, group) }).filter((item): item is Connection => Boolean(item))).reduce<Connection[]>((unique, item) => { const key = `${item.source}:${rowTitle(item.row, item.source)}:${item.source === 'spotify' ? item.row.artist_name : ''}`; return unique.some((existing) => `${existing.source}:${rowTitle(existing.row, existing.source)}:${existing.source === 'spotify' ? existing.row.artist_name : ''}` === key) ? unique : [...unique, item] }, []).sort((a, b) => b.score - a.score || b.records - a.records || a.minutes - b.minutes); return candidates.slice(0, 8) }, [data, selected]); const current = connections[active] ?? null; const choose = (connection: Connection) => { setSelected({ row: connection.row, source: connection.source }); setActive(0) }; if (!data || !selected) return <main className="game-shell"><GameHeader /><div className="archive-loading"><strong>CONNECTING RECORDS...</strong><span>BUILDING EXPLAINABLE LINKS</span></div></main>; return <main className="game-shell connect-shell"><div className="game-bg-art" aria-hidden="true"><div className="silhouette" /><div className="map-lines" /><div className="wave wave-a" /><div className="receipt-shard shard-a" /></div><GameHeader archive /><div className="connect-header"><div><span className="archive-kicker">{'LIFE//RECEIPTS'}</span><h1>CONNECT THE DOTS</h1><p>Find the moments hiding between the records.</p></div><button className="back-button" onClick={onBack}>◀ MAIN MENU</button></div><div className="connect-layout"><section className="selected-receipt"><span className="notice-kicker">SELECTED RECEIPT</span><div className="selected-type">{connectionLabel(selected.source)}</div><h2>{rowTitle(selected.row, selected.source)}</h2><p>{selected.source === 'spotify' ? `${selected.row.artist_name || 'UNKNOWN ARTIST'} // ${selected.row.album_name || 'UNKNOWN ALBUM'}` : selected.source === 'household' ? `${selected.row.Subcategory || 'GENERAL'} // ${selected.row['Income/Expense'] || 'UNSPECIFIED'}` : `${selected.row.category || 'GENERAL'} // ${selected.row.city || 'UNKNOWN CITY'}`}</p><strong>{formatDate(selected.row, selected.source)}</strong><button className="find-button" onClick={() => setActive(0)}>[ FIND CONNECTIONS ]</button><div className="cluster-note">{connections.length >= 3 ? <><b>CLUSTER DETECTED</b><span>{connections.length + 1} receipts with measurable overlaps.</span><em>STORY CANDIDATE</em></> : <><b>NO STRONG CONNECTIONS FOUND</b><span>Try another receipt or broaden the search.</span></>}</div></section><section className="constellation" aria-label="Interactive connection constellation"><div className="constellation-grid" /><div className="orbit-line" /><div className="center-node"><span>{connectionLabel(selected.source)}</span><b>SELECTED</b></div>{connections.map((connection, index) => { const angle = (index / Math.max(connections.length, 1)) * Math.PI * 2 - Math.PI / 2; const radius = 34; return <button key={`${connection.source}-${index}-${rowTitle(connection.row, connection.source)}`} className={`orbit-node orbit-node-${connection.score >= 65 ? 'strong' : 'medium'} ${active === index ? 'orbit-node-active' : ''}`} style={{ left: `${50 + Math.cos(angle) * radius}%`, top: `${50 + Math.sin(angle) * radius}%` }} onMouseEnter={() => setActive(index)} onFocus={() => setActive(index)} onClick={() => choose(connection)} aria-label={`${rowTitle(connection.row, connection.source)}, ${connection.score}% connection`}><span>{connectionLabel(connection.source).slice(0, 1)}</span></button> })}<div className="constellation-caption">{current ? `${current.score}% // ${current.reasons.join(' // ')}` : 'SELECT A NODE TO INSPECT'}</div></section><aside className="connection-analysis"><span className="notice-kicker">CONNECTION ANALYSIS</span><div className="analysis-selected">SELECTED<br /><b>{rowTitle(selected.row, selected.source)}</b><small>{connectionLabel(selected.source)} {' // '} {formatDate(selected.row, selected.source)}</small></div><h3>CONNECTED MOMENTS</h3><div className="connection-list">{connections.length ? connections.map((connection, index) => <ConnectionCard key={`${connection.source}-${index}-${rowTitle(connection.row, connection.source)}`} connection={connection} index={index} selected={active === index} onClick={() => choose(connection)} />) : <p className="no-results">NO STRONG CONNECTIONS FOUND<br /><small>Try another receipt or broaden the search.</small></p>}</div></aside></div><footer className="game-footer"><div className="player-line"><span>PLAYER</span><strong>CONNECTION ENGINE // READY</strong></div><div className="controls"><span>▲ SELECT</span><span>○ BACK</span><span>▶ START</span></div></footer></main> }

type LabSection = 'rhythm' | 'listening' | 'spending' | 'bursts' | 'repeated' | 'unusual'
const labSections: [LabSection, string][] = [['rhythm','ACTIVITY RHYTHM'],['listening','LISTENING DNA'],['spending','SPENDING DNA'],['bursts','ACTIVITY BURSTS'],['repeated','REPEATED BEHAVIOR'],['unusual','UNUSUAL ACTIVITY']]
function fieldCount(rows: Row[], field: string) { const counts = new Map<string, number>(); rows.forEach((row) => { const value = row[field]; if (value) counts.set(value, (counts.get(value) || 0) + 1) }); return [...counts.entries()].sort((a,b) => b[1] - a[1]) }
function parseHour(row: Row, source: Exclude<SourceKey,'all'>) { const raw = source === 'spotify' ? row.ts : source === 'household' ? row.Date : row.trans_date_trans_time; const date = raw ? new Date(raw.replace(' UTC','')) : null; return date && !Number.isNaN(date.getTime()) ? date.getHours() : null }
function PatternLab({ onBack, onExplore }: { onBack: () => void; onExplore: (source: Exclude<SourceKey,'all'>, search?: string) => void }) { const [data, setData] = useState<Record<Exclude<SourceKey,'all'>, Row[]> | null>(null); const [section, setSection] = useState<LabSection>('rhythm'); const [period, setPeriod] = useState<number | null>(null); useEffect(() => { loadArchiveData().then(setData) }, []); const analysis = useMemo(() => { if (!data) return null; const spotify = data.spotify; const household = data.household; const india = data.indiaTransactions; const rhythm = Array.from({length:24},(_,hour) => { const rows = ([['spotify',spotify],['household',household],['indiaTransactions',india]] as const).flatMap(([source,items]) => items.filter((row) => parseHour(row,source) === hour).map((row) => ({row,source}))); const source = fieldCount(rows.map((item) => ({source:item.source})), 'source')[0]?.[0] || 'NONE'; return {hour, count:rows.length, source} }); const artists = fieldCount(spotify,'artist_name'); const tracks = fieldCount(spotify,'track_name'); const albums = fieldCount(spotify,'album_name'); const totalMs = spotify.reduce((sum,row) => sum + (Number(row.ms_played)||0),0); const skipped = spotify.filter(row => row.skipped === 'True').length; const platforms = fieldCount(spotify,'platform'); const categories = fieldCount(household,'Category'); const merchants = fieldCount(india,'merchant'); const expenses = household.filter(row => row['Income/Expense']?.toLowerCase() === 'expense').reduce((sum,row)=>sum+(Number(row.Amount)||0),0); const income = household.filter(row => row['Income/Expense']?.toLowerCase() === 'income').reduce((sum,row)=>sum+(Number(row.Amount)||0),0); const fraud = india.filter(row=>row.is_fraud === '1').length; const repeated = artists[0] ? `${artists[0][0]} appears most frequently in the listening archive.` : 'No repeated artist pattern available.'; return {spotify,household,india,rhythm,artists,tracks,albums,totalMs,skipped,platforms,categories,merchants,expenses,income,fraud,repeated} }, [data]); if (!analysis) return <main className="game-shell"><GameHeader /><div className="archive-loading"><strong>DECODING PATTERN LAB...</strong><span>AGGREGATING REAL RECORDS</span></div></main>; const max = Math.max(...analysis.rhythm.map(item=>item.count),1); const sectionTitle = labSections.find(([key])=>key===section)?.[1] || ''; const explore = (source: Exclude<SourceKey,'all'>, search?: string) => onExplore(source, search); return <main className="game-shell lab-shell"><div className="game-bg-art" aria-hidden="true"><div className="silhouette" /><div className="map-lines" /><div className="wave wave-a" /><div className="receipt-shard shard-a" /></div><GameHeader archive /><div className="lab-header"><div><span className="archive-kicker">{'LIFE//RECEIPTS'}</span><h1>PATTERN LAB</h1><p>Patterns hidden inside the archive.</p></div><button className="back-button" onClick={onBack}>◀ MAIN MENU</button></div><div className="lab-layout"><aside className="lab-selector"><span className="archive-kicker">ANALYSIS MODULES</span>{labSections.map(([key,label],index)=><button key={key} className={`lab-item ${section===key?'lab-item-active':''}`} onClick={()=>{setSection(key);setPeriod(null)}}><span className="menu-cursor" aria-hidden="true"><i /></span>{label}<small>{String(index+1).padStart(2,'0')}</small></button>)}</aside><section className="lab-content"><div className="insight-strip"><span className="notice-kicker">PATTERN DETECTED</span><strong>{section==='rhythm'?'ACTIVITY RHYTHM':section==='listening'?'LISTENING DNA':section==='spending'?'SPENDING DNA':section==='bursts'?'ACTIVITY BURSTS':section==='repeated'?'REPEATED BEHAVIOR':'UNUSUAL ACTIVITY'}</strong><p>{section==='rhythm'?'Compare real activity across every hour of the day.':section==='listening'?`${analysis.spotify.length.toLocaleString()} listening records across ${analysis.artists.length.toLocaleString()} artists.`:section==='spending'?`Household income and expenses plus ${analysis.india.length.toLocaleString()} card transactions.`:section==='bursts'?'Dense periods are shown only when the loaded records support them.':section==='repeated'?analysis.repeated:'Measured differences, concentrations and outliers only.'}</p></div><div className="lab-panel"><div className="lab-panel-heading"><span>01 // {sectionTitle}</span><b>REAL RECORDS // MEMOIZED AGGREGATES</b></div>{section==='rhythm' && <><div className="rhythm-scale"><span>00</span><span>06</span><span>12</span><span>18</span><span>24</span></div><div className="rhythm-chart" aria-label="Activity records by hour">{analysis.rhythm.map(item=><button key={item.hour} className={`rhythm-bar ${period===item.hour?'rhythm-bar-selected':''}`} style={{height:`${Math.max(5,item.count/max*100)}%`}} onClick={()=>setPeriod(item.hour)} aria-label={`${item.hour}:00, ${item.count.toLocaleString()} records, dominant source ${item.source}`}><i /><small>{item.hour}</small></button>)}</div><div className="lab-evidence">{period === null ? 'SELECT AN HOUR TO INSPECT THE UNDERLYING RECORDS.' : <><b>{String(period).padStart(2,'0')}:00 — {analysis.rhythm[period].count.toLocaleString()} RECORDS</b><span>DOMINANT SOURCE // {analysis.rhythm[period].source}</span><button className="connect-button" onClick={()=>explore(analysis.rhythm[period].source==='spotify'?'spotify':analysis.rhythm[period].source==='household'?'household':'indiaTransactions')}>[ EXPLORE RECEIPTS ]</button></>}</div></>}{section==='listening' && <div className="lab-stat-grid"><div><span>LISTENING TIME</span><b>{Math.round(analysis.totalMs/3600000).toLocaleString()} HR</b></div><div><span>LISTENING RECORDS</span><b>{analysis.spotify.length.toLocaleString()}</b></div><div><span>UNIQUE ARTISTS</span><b>{analysis.artists.length.toLocaleString()}</b></div><div><span>UNIQUE TRACKS</span><b>{analysis.tracks.length.toLocaleString()}</b></div><div><span>SKIP RATE</span><b>{(analysis.skipped/analysis.spotify.length*100).toFixed(1)}%</b></div><div><span>PLATFORMS</span><b>{analysis.platforms.length}</b></div><div className="lab-rankings"><span>TOP ARTISTS</span>{analysis.artists.slice(0,6).map(([name,count])=><button key={name} onClick={()=>explore('spotify',name)}><b>{name}</b><small>{count.toLocaleString()} RECORDS</small></button>)}</div><div className="lab-rankings"><span>TOP TRACKS</span>{analysis.tracks.slice(0,6).map(([name,count])=><button key={name} onClick={()=>explore('spotify',name)}><b>{name}</b><small>{count.toLocaleString()} PLAYS</small></button>)}</div></div>}{section==='spending' && <div className="lab-stat-grid"><div><span>HOUSEHOLD INCOME</span><b>{analysis.income.toLocaleString()} INR</b></div><div><span>HOUSEHOLD EXPENSES</span><b>{analysis.expenses.toLocaleString()} INR</b></div><div><span>HOUSEHOLD CATEGORIES</span><b>{analysis.categories.length}</b></div><div><span>CARD TRANSACTIONS</span><b>{analysis.india.length.toLocaleString()}</b></div><div><span>CARD FRAUD RECORDS</span><b>{analysis.fraud.toLocaleString()}</b></div><div><span>CARD MERCHANTS</span><b>{analysis.merchants.length.toLocaleString()}</b></div><div className="lab-rankings"><span>HOUSEHOLD CATEGORIES</span>{analysis.categories.slice(0,8).map(([name,count])=><button key={name} onClick={()=>explore('household',name)}><b>{name}</b><small>{count.toLocaleString()} RECORDS</small></button>)}</div><div className="lab-rankings"><span>TOP MERCHANTS</span>{analysis.merchants.slice(0,8).map(([name,count])=><button key={name} onClick={()=>explore('indiaTransactions',name)}><b>{name}</b><small>{count.toLocaleString()} RECORDS</small></button>)}</div></div>}{section==='bursts' && <div className="lab-stat-grid"><div><span>ACTIVITY WINDOWS</span><b>{analysis.rhythm.filter(item=>item.count>max*.75).length}</b></div><div><span>PEAK HOUR</span><b>{String(analysis.rhythm.reduce((a,b)=>b.count>a.count?b:a).hour).padStart(2,'0')}:00</b></div><div className="lab-evidence"><span>WINDOWS ARE DERIVED FROM HOURLY RECORD DENSITY ACROSS THE LOADED ARCHIVE.</span><button className="connect-button" onClick={()=>explore('spotify')}>[ EXPLORE CLUSTER ]</button></div></div>}{section==='repeated' && <div className="lab-rankings standalone">{analysis.artists.slice(0,10).map(([name,count])=><button key={name} onClick={()=>explore('spotify',name)}><b>{name}</b><small>{count.toLocaleString()} records // {((count/analysis.spotify.length)*100).toFixed(2)}%</small></button>)}</div>}{section==='unusual' && <div className="lab-stat-grid"><div><span>PEAK HOUR RECORDS</span><b>{Math.max(...analysis.rhythm.map(item=>item.count)).toLocaleString()}</b></div><div><span>LOWEST HOUR RECORDS</span><b>{Math.min(...analysis.rhythm.map(item=>item.count)).toLocaleString()}</b></div><div><span>SKIPPED LISTENING</span><b>{analysis.skipped.toLocaleString()}</b></div><div><span>FRAUD FLAG RECORDS</span><b>{analysis.fraud.toLocaleString()}</b></div><div className="lab-evidence"><span>VALUES ARE CALCULATED FROM THE COMPLETE UPLOADED DATASETS.</span></div></div>}</div></section></div><footer className="game-footer"><div className="player-line"><span>PLAYER</span><strong>PATTERN LAB // READY</strong></div><div className="controls"><span>▲ SELECT</span><span>○ BACK</span><span>▶ START</span></div></footer></main> }

type StoryCandidate = { rows: Row[]; source: Exclude<SourceKey,'all'>; start: Date; end: Date; artists: string[]; title: string }
function storyTime(row: Row, source: Exclude<SourceKey,'all'>) { const value = source === 'spotify' ? row.ts : source === 'household' ? row.Date : row.trans_date_trans_time; const date = value ? new Date(value.replace(' UTC','')) : null; return date && !Number.isNaN(date.getTime()) ? date : null }
function buildStoryCandidates(data: Record<Exclude<SourceKey,'all'>, Row[]>): StoryCandidate[] { const spotify = data.spotify.map(row => ({ row, time: storyTime(row,'spotify') })).filter((item): item is {row:Row;time:Date} => Boolean(item.time)).sort((a,b)=>a.time.getTime()-b.time.getTime()); const candidates: StoryCandidate[] = []; const addCluster = (cluster: {row:Row;time:Date}[]) => { for (let index=0; index<cluster.length; index+=7) { const slice=cluster.slice(index,index+7); if (slice.length>=3) candidates.push(makeStoryCandidate(slice)) } }; let cluster: {row:Row;time:Date}[] = []; for (const item of spotify) { if (!cluster.length || item.time.getTime()-cluster[cluster.length-1].time.getTime() <= 15*60000) cluster.push(item); else { addCluster(cluster); cluster=[item] } } if (cluster.length) addCluster(cluster); return candidates.sort((a,b)=>b.rows.length-a.rows.length || b.end.getTime()-b.start.getTime()).slice(0,4) }
function makeStoryCandidate(cluster: {row:Row;time:Date}[]): StoryCandidate { const artists=[...new Set(cluster.map(item=>item.row.artist_name).filter(Boolean))]; return { rows: cluster.map(item=>item.row), source:'spotify', start:cluster[0].time, end:cluster[cluster.length-1].time, artists, title: artists.length > 1 ? 'HIGH-DENSITY LISTENING ACTIVITY' : 'REPEATED LISTENING ACTIVITY' } }
function storyStamp(date: Date) { return date.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit'}) }
function StoryMode({ onBack, onExplore, onConnect }: { onBack: () => void; onExplore: (source: Exclude<SourceKey,'all'>, search?: string) => void; onConnect: (row:Row, source:Exclude<SourceKey,'all'>) => void }) { const [data,setData]=useState<Record<Exclude<SourceKey,'all'>,Row[]>|null>(null); const [candidate,setCandidate]=useState<StoryCandidate|null>(null); const [moment,setMoment]=useState(0); useEffect(()=>{loadArchiveData().then(setData)},[]); const candidates=useMemo(()=>data?buildStoryCandidates(data):[],[data]); const current=candidate?.rows[moment] ?? null; const currentTime=current?storyTime(current,'spotify'):null; const previous=candidate && moment>0 ? storyTime(candidate.rows[moment-1],'spotify'):null; const relation=currentTime&&previous ? Math.round((currentTime.getTime()-previous.getTime())/1000) : 0; const next=useCallback(()=>setMoment(value=>Math.min(value+1,(candidate?.rows.length||1)-1)),[candidate]); const prev=()=>setMoment(value=>Math.max(0,value-1)); useEffect(()=>{const key=(event:KeyboardEvent)=>{if(!candidate)return;if(event.key==='ArrowRight')next();if(event.key==='ArrowLeft')prev();if(event.key==='Escape'){if(candidate)setCandidate(null);else onBack()};if(event.key==='Enter'&&moment===candidate.rows.length-1) onExplore('spotify')};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[candidate,moment,next,onBack,onExplore]); if(!data)return <main className="game-shell"><GameHeader/><div className="archive-loading"><strong>DECODING STORY ARCHIVE...</strong><span>SEARCHING REAL CLUSTERS</span></div></main>; return <main className="game-shell story-shell"><div className="game-bg-art" aria-hidden="true"><div className="silhouette"/><div className="map-lines"/><div className="wave wave-a"/><div className="receipt-shard shard-a"/></div><GameHeader archive/><div className="story-header"><div><span className="archive-kicker">{'LIFE//RECEIPTS'}</span><h1>STORY MODE</h1><p>FOLLOW THE MOMENTS THAT CONNECT.</p></div><button className="back-button" onClick={candidate?()=>setCandidate(null):onBack}>◀ {candidate?'STORY ARCHIVE':'MAIN MENU'}</button></div>{!candidate?<section className="story-archive"><div className="story-section-title"><span>STORY ARCHIVE</span><b>{candidates.length.toString().padStart(2,'0')} CANDIDATES</b></div>{candidates.length?candidates.map((item,index)=><button className="chapter-candidate" key={`${item.start.toISOString()}-${index}`} onClick={()=>{setCandidate(item);setMoment(0)}}><span className="chapter-no">{String(index+1).padStart(2,'0')}</span><span className="candidate-copy"><b>CHAPTER CANDIDATE</b><strong>{item.start.toLocaleDateString('en-CA')}<br/>{storyStamp(item.start)} — {storyStamp(item.end)}</strong><small>{item.rows.length} RECEIPTS // 1 SOURCE // {item.artists.length} ARTISTS</small><em>PATTERN<br/><span>{item.title}</span></em></span><span className="enter-chapter">[ ENTER CHAPTER ]</span></button>):<div className="story-empty"><strong>NO STORY CANDIDATES FOUND</strong><span>Explore the archive to discover connected moments.</span></div>}</section>:<section className="chapter-screen"><div className="chapter-hud"><span>CHAPTER {String(candidates.indexOf(candidate)+1).padStart(2,'0')} / {String(candidates.length).padStart(2,'0')}</span><b>MOMENT {String(moment+1).padStart(2,'0')} / {String(candidate.rows.length).padStart(2,'0')}</b></div><div className="chapter-layout"><aside className="chapter-signal"><span className="notice-kicker">CHAPTER SIGNAL</span><strong>{candidate.rows.length} listening records occurred within {Math.max(1,Math.round((candidate.end.getTime()-candidate.start.getTime())/60000))} minutes.</strong><span>{candidate.artists.length} artists accounted for the activity.</span><div className="moment-index">{candidate.rows.map((_,index)=><button className={index===moment?'moment-index-active':''} key={index} onClick={()=>setMoment(index)} aria-label={`Moment ${index+1}`}>M{String(index+1).padStart(2,'0')}</button>)}</div></aside><section className="moment-detail"><span className="notice-kicker">MOMENT {String(moment+1).padStart(2,'0')} / {String(candidate.rows.length).padStart(2,'0')}</span><div className="selected-type">MUSIC</div><h2>{current?.track_name||'UNTITLED TRACK'}</h2><p>ARTIST<br/><strong>{current?.artist_name||'UNKNOWN ARTIST'}</strong></p><p>TIME<br/><strong>{currentTime?storyStamp(currentTime):'TIME UNKNOWN'}</strong></p>{moment>0&&<div className="moment-connection"><b>CONNECTED</b><span>+ {relation<60?`${relation} seconds apart`:`${Math.round(relation/60)} minutes apart`}</span><span>+ Same listening archive</span><strong>STRENGTH<br/><em>{relation<180?82:64}%</em></strong></div>}<button className="find-button" onClick={moment===candidate.rows.length-1?()=>onExplore('spotify'):next}>{moment===candidate.rows.length-1?'[ EXPLORE RECEIPTS ]':'[ NEXT MOMENT ]'}</button></section><section className="chapter-visual"><div className="chapter-line"/>{candidate.rows.map((_,index)=><button key={index} className={`chapter-node ${index===moment?'chapter-node-active':''}`} style={{left:`${8+(index/(Math.max(candidate.rows.length-1,1)))*84}%`}} onClick={()=>setMoment(index)} aria-label={`Moment ${index+1}`}>M{String(index+1).padStart(2,'0')}</button>)}<span className="chapter-visual-label">REAL RECEIPTS // TEMPORAL RELATIONSHIPS</span></section></div><div className="chapter-actions"><button onClick={()=>setMoment(0)}>[ REPLAY CHAPTER ]</button><button onClick={()=>onExplore('spotify')} >[ EXPLORE RECEIPTS ]</button><button onClick={()=>current&&onConnect(current,'spotify')}>[ CONNECT THE DOTS ]</button><button onClick={()=>setCandidate(null)}>[ BACK TO STORY ARCHIVE ]</button></div>{moment===candidate.rows.length-1&&<div className="chapter-complete"><span className="notice-kicker">CHAPTER COMPLETE</span><h2>WHAT THE ARCHIVE SHOWS</h2><p>{candidate.rows.length} music records occurred between {storyStamp(candidate.start)} and {storyStamp(candidate.end)}. {candidate.artists.length} artists accounted for the activity.</p><div><b>{candidate.rows.length} RECEIPTS</b><b>{Math.max(1,Math.round((candidate.end.getTime()-candidate.start.getTime())/60000))} MINUTES</b><b>{candidate.artists.length} ARTISTS</b><b>1 STRONG CLUSTER</b></div></div>}</section>}<footer className="game-footer"><div className="player-line"><span>PLAYER</span><strong>STORY MODE // {candidate?'CHAPTER ACTIVE':'READY'}</strong></div><div className="controls"><span>◀ PREV</span><span>▶ NEXT</span><span>○ BACK</span></div></footer></main> }

type Preferences = { reducedMotion: boolean; compact: boolean; keyboardHelp: boolean }
const defaultPreferences: Preferences = { reducedMotion: false, compact: false, keyboardHelp: true }
const settingsOptions = [['REDUCED MOTION', 'reducedMotion'], ['VISUAL DENSITY', 'compact'], ['KEYBOARD HELP', 'keyboardHelp']] as const
function readPreferences(): Preferences { if (typeof window === 'undefined') return defaultPreferences; try { const saved = JSON.parse(window.localStorage.getItem('life-receipts-preferences') || '{}'); return { ...defaultPreferences, ...saved } } catch { return defaultPreferences } }
function SettingsScreen({ onBack }: { onBack: () => void }) { const [preferences, setPreferences] = useState<Preferences>(() => { const loaded = readPreferences(); if (typeof window !== 'undefined' && !window.localStorage.getItem('life-receipts-preferences') && window.matchMedia('(prefers-reduced-motion: reduce)').matches) loaded.reducedMotion = true; return loaded }); const [selected, setSelected] = useState(0); const [notice, setNotice] = useState(''); const options = settingsOptions; useEffect(() => { document.documentElement.dataset.reducedMotion = preferences.reducedMotion ? 'true' : 'false'; document.documentElement.dataset.density = preferences.compact ? 'compact' : 'normal'; document.documentElement.dataset.keyboardHelp = preferences.keyboardHelp ? 'on' : 'off'; window.localStorage.setItem('life-receipts-preferences', JSON.stringify(preferences)) }, [preferences]); const activate = useCallback((index: number) => { if (index < options.length) { const key = options[index][1]; setPreferences((value) => ({ ...value, [key]: !value[key] })); setNotice('') } else { const reset = { ...defaultPreferences, reducedMotion: window.matchMedia('(prefers-reduced-motion: reduce)').matches }; setPreferences(reset); setNotice('SETTINGS RESET\\nPreferences restored to defaults.') } }, [options]) ; useEffect(() => { const onKey = (event: KeyboardEvent) => { if (event.key === 'Escape') onBack(); if (event.key === 'ArrowDown') { event.preventDefault(); setSelected((value) => (value + 1) % 4) } if (event.key === 'ArrowUp') { event.preventDefault(); setSelected((value) => (value + 3) % 4) } if ((event.key === 'Enter' || event.key === ' ') && !event.repeat) { event.preventDefault(); activate(selected) } }; window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey) }, [activate, onBack, selected]); return <main className="game-shell settings-shell"><GameHeader/><div className="settings-panel"><div className="settings-heading"><span className="archive-kicker">SYSTEM CONFIGURATION</span><h1>SETTINGS</h1></div><div className="settings-list">{options.map(([label, key], index) => <button key={key} className={selected === index ? 'settings-item settings-selected' : 'settings-item'} onClick={() => { setSelected(index); activate(index) }}><span>{`${String(index + 1).padStart(2, '0')} // ${label}`}</span><b>{preferences[key] ? 'ON' : 'OFF'}</b></button>)}<button className={selected === 3 ? 'settings-item settings-selected' : 'settings-item'} onClick={() => { setSelected(3); activate(3) }}><span>04 // RESET SETTINGS</span><b>RESET</b></button></div>{notice && <p className="settings-notice">{notice}</p>}<button className="back-button" onClick={onBack}>◀ MAIN MENU</button></div></main> }

export default function Page() { const [screen, setScreen] = useState<'menu' | 'archive' | 'connect' | 'patterns' | 'story' | 'settings'>('menu'); const [selectedReceipt, setSelectedReceipt] = useState<{ row: Row; source: Exclude<SourceKey, 'all'> }>(); const [archiveQuery, setArchiveQuery] = useState<{ source?: Exclude<SourceKey,'all'>; search?: string }>({}); const onBack = useCallback(() => setScreen('menu'), []); const openConnections = useCallback((row: Row, source: Exclude<SourceKey, 'all'>) => { setSelectedReceipt({ row, source }); setScreen('connect') }, []); const openExplore = useCallback((source: Exclude<SourceKey,'all'>, search?: string) => { setArchiveQuery({ source, search }); setScreen('archive') }, []); return screen === 'settings' ? <SettingsScreen onBack={onBack} /> : screen === 'archive' ? <ArchiveScreen onBack={onBack} onConnect={openConnections} initialSource={archiveQuery.source} initialSearch={archiveQuery.search} /> : screen === 'connect' ? <ConnectScreen onBack={onBack} initialSelection={selectedReceipt} /> : screen === 'patterns' ? <PatternLab onBack={onBack} onExplore={openExplore} /> : screen === 'story' ? <StoryMode onBack={onBack} onExplore={openExplore} onConnect={openConnections} /> : <MainMenu onStory={() => setScreen('story')} onArchive={() => setScreen('archive')} onConnect={() => setScreen('connect')} onPatternLab={() => setScreen('patterns')} onSettings={() => setScreen('settings')} /> }
